#import "ABMCShortcutListController.h"
#import "ABMCUIHelpers.h"
#import <sqlite3.h>
#import <math.h>
static BOOL UUIDOK(NSString*v){return[v isKindOfClass:NSString.class]&&[[NSUUID alloc]initWithUUIDString:v]!=nil;}
@interface ABMCShortcutListController ()<UISearchBarDelegate>@end
@implementation ABMCShortcutListController{NSString*_key,*_query,*_expanded;NSArray*_all,*_folders;}
- (instancetype)initWithPreferenceKey:(NSString*)key{if((self=[super initWithStyle:UITableViewStyleInsetGrouped])){_key=[key copy];self.title=@"指令列表";}return self;}
- (void)viewDidLoad{[super viewDidLoad];_query=@"";self.tableView.rowHeight=44.0;self.tableView.estimatedRowHeight=44.0;[self refreshHeader];self.navigationItem.rightBarButtonItem=[[UIBarButtonItem alloc]initWithTitle:@"清空" style:UIBarButtonItemStylePlain target:self action:@selector(clearAll)];[self reloadData];}
- (void)refreshHeader{UIView*h=ABMCSelectedActionsBanner(_key,self);CGFloat bannerHeight=h.bounds.size.height;for(UIView *subview in h.subviews){CGRect frame=subview.frame;frame.origin.y+=60;subview.frame=frame;}UISearchBar*s=[[UISearchBar alloc]initWithFrame:CGRectMake(8,0,h.bounds.size.width-16,56)];s.placeholder=@"搜索快捷指令";s.delegate=self;CGRect f=h.frame;f.size.height=bannerHeight+60;h.frame=f;[h addSubview:s];self.tableView.tableHeaderView=h;dispatch_async(dispatch_get_main_queue(),^{CGFloat width=self.tableView.bounds.size.width;if(width>100 && fabs(h.bounds.size.width-width)>.5){CGRect f=h.frame;f.size.width=width;h.frame=f;self.tableView.tableHeaderView=h;}});}
- (void)clearAll{ABMCStoreSelectedActions(_key,@[]);[self refreshHeader];[self.tableView reloadData];}
- (NSString *)bestColumnInTable:(NSString *)table database:(sqlite3 *)db names:(NSArray *)needles {
    sqlite3_stmt *stmt=NULL;NSString *found=nil;NSString *sql=[NSString stringWithFormat:@"PRAGMA table_info(%@)",table];
    if(sqlite3_prepare_v2(db,sql.UTF8String,-1,&stmt,NULL)==SQLITE_OK)while(sqlite3_step(stmt)==SQLITE_ROW){const char *raw=(const char *)sqlite3_column_text(stmt,1);if(!raw)continue;NSString *name=[NSString stringWithUTF8String:raw].uppercaseString;for(NSString *needle in needles)if([name containsString:needle]){found=[NSString stringWithUTF8String:raw];break;}if(found)break;}if(stmt)sqlite3_finalize(stmt);return found;
}
- (void)reloadData {
    NSMutableDictionary *work=[NSMutableDictionary dictionary],*folders=[NSMutableDictionary dictionary],*shortcutsByPrimaryKey=[NSMutableDictionary dictionary];
    NSArray *paths=@[@"/private/var/mobile/Library/Shortcuts/Shortcuts.sqlite",@"/var/mobile/Library/Shortcuts/Shortcuts.sqlite",@"/private/var/mobile/Library/Shortcuts/Shortcuts.db",@"/var/mobile/Library/Shortcuts/Shortcuts.db"];
    for(NSString *path in paths){
        sqlite3 *db=NULL;if(sqlite3_open_v2(path.UTF8String,&db,SQLITE_OPEN_READONLY|SQLITE_OPEN_NOMUTEX,NULL)!=SQLITE_OK){if(db)sqlite3_close(db);continue;}
        NSMutableArray *allTables=[NSMutableArray array],*folderTables=[NSMutableArray array];sqlite3_stmt *tables=NULL;
        if(sqlite3_prepare_v2(db,"SELECT name FROM sqlite_master WHERE type='table'",-1,&tables,NULL)==SQLITE_OK)while(sqlite3_step(tables)==SQLITE_ROW){const char *raw=(const char *)sqlite3_column_text(tables,0);if(!raw)continue;NSString *name=[NSString stringWithUTF8String:raw];[allTables addObject:name];if([name.uppercaseString containsString:@"FOLDER"])[folderTables addObject:name];}if(tables)sqlite3_finalize(tables);
        for(NSString *table in folderTables){NSString *nameColumn=[self bestColumnInTable:table database:db names:@[@"DISPLAYNAME",@"TITLE",@"NAME"]];if(!nameColumn.length)continue;NSString *sql=[NSString stringWithFormat:@"SELECT Z_PK,%@ FROM %@ WHERE %@ IS NOT NULL",nameColumn,table,nameColumn];sqlite3_stmt *rows=NULL;if(sqlite3_prepare_v2(db,sql.UTF8String,-1,&rows,NULL)==SQLITE_OK)while(sqlite3_step(rows)==SQLITE_ROW){const char *raw=(const char *)sqlite3_column_text(rows,1);if(!raw)continue;NSString *fid=[NSString stringWithFormat:@"%lld",sqlite3_column_int64(rows,0)];folders[fid]=[@{@"id":fid,@"name":[NSString stringWithUTF8String:raw],@"items":[NSMutableArray array]}mutableCopy];}if(rows)sqlite3_finalize(rows);}
        NSMutableArray *folderColumns=[NSMutableArray array];sqlite3_stmt *columns=NULL;if(sqlite3_prepare_v2(db,"PRAGMA table_info(ZSHORTCUT)",-1,&columns,NULL)==SQLITE_OK)while(sqlite3_step(columns)==SQLITE_ROW){const char *raw=(const char *)sqlite3_column_text(columns,1);if(raw){NSString *column=[NSString stringWithUTF8String:raw];if([column.uppercaseString containsString:@"FOLDER"])[folderColumns addObject:column];}}if(columns)sqlite3_finalize(columns);
        NSString *extra=folderColumns.count?[@",x." stringByAppendingString:[folderColumns componentsJoinedByString:@",x."]]:@"";NSString *sql=[NSString stringWithFormat:@"SELECT x.Z_PK,x.ZNAME,x.ZWORKFLOWID,COALESCE(i.ZGLYPHNUMBER,0),COALESCE(i.ZBACKGROUNDCOLORVALUE,0)%@ FROM ZSHORTCUT x LEFT JOIN ZSHORTCUTICON i ON i.Z_PK=x.ZICON WHERE x.ZNAME IS NOT NULL AND x.ZWORKFLOWID IS NOT NULL AND COALESCE(x.ZTOMBSTONED,0)=0",extra];sqlite3_stmt *rows=NULL;
        if(sqlite3_prepare_v2(db,sql.UTF8String,-1,&rows,NULL)==SQLITE_OK)while(sqlite3_step(rows)==SQLITE_ROW){const char *rn=(const char *)sqlite3_column_text(rows,1),*ri=(const char *)sqlite3_column_text(rows,2);if(!rn||!ri)continue;NSString *name=[NSString stringWithUTF8String:rn],*ident=[[NSString stringWithUTF8String:ri]uppercaseString];if(!name.length||!UUIDOK(ident))continue;NSMutableDictionary *item=[@{@"name":name,@"id":ident,@"glyph":@(sqlite3_column_int64(rows,3)),@"color":@(sqlite3_column_int64(rows,4))}mutableCopy];work[ident]=item;shortcutsByPrimaryKey[[NSString stringWithFormat:@"%lld",sqlite3_column_int64(rows,0)]]=item;for(NSUInteger c=0;c<folderColumns.count;c++)if(sqlite3_column_type(rows,(int)c+5)!=SQLITE_NULL){NSString *fid=[NSString stringWithFormat:@"%lld",sqlite3_column_int64(rows,(int)c+5)];NSMutableArray *items=folders[fid][@"items"];if(items&&![items containsObject:item])[items addObject:item];}}if(rows)sqlite3_finalize(rows);
        // iOS releases that model folder membership as a Core Data join table
        // do not expose a FOLDER column on ZSHORTCUT. Discover that relation
        // schema instead of assuming a version-specific table name.
        for(NSString *table in allTables){if([table isEqualToString:@"ZSHORTCUT"])continue;sqlite3_stmt *info=NULL;NSString *shortcutColumn=nil,*folderColumn=nil;NSString *pragma=[NSString stringWithFormat:@"PRAGMA table_info(%@)",table];if(sqlite3_prepare_v2(db,pragma.UTF8String,-1,&info,NULL)==SQLITE_OK)while(sqlite3_step(info)==SQLITE_ROW){const char *raw=(const char *)sqlite3_column_text(info,1);if(!raw)continue;NSString *column=[NSString stringWithUTF8String:raw],*upper=column.uppercaseString;if(!shortcutColumn&&[upper containsString:@"SHORTCUT"])shortcutColumn=column;if(!folderColumn&&[upper containsString:@"FOLDER"])folderColumn=column;}if(info)sqlite3_finalize(info);if(!shortcutColumn.length||!folderColumn.length)continue;NSString *join=[NSString stringWithFormat:@"SELECT %@,%@ FROM %@",shortcutColumn,folderColumn,table];sqlite3_stmt *links=NULL;if(sqlite3_prepare_v2(db,join.UTF8String,-1,&links,NULL)==SQLITE_OK)while(sqlite3_step(links)==SQLITE_ROW){NSString *sid=[NSString stringWithFormat:@"%lld",sqlite3_column_int64(links,0)],*fid=[NSString stringWithFormat:@"%lld",sqlite3_column_int64(links,1)];NSMutableDictionary *item=shortcutsByPrimaryKey[sid];NSMutableArray *items=folders[fid][@"items"];if(item&&items&&![items containsObject:item])[items addObject:item];}if(links)sqlite3_finalize(links);}
        sqlite3_close(db);
    }
    _all=[work.allValues sortedArrayUsingComparator:^NSComparisonResult(NSDictionary*a,NSDictionary*b){return[a[@"name"] localizedCaseInsensitiveCompare:b[@"name"]];}];_folders=[folders.allValues sortedArrayUsingComparator:^NSComparisonResult(NSDictionary*a,NSDictionary*b){return[a[@"name"] localizedCaseInsensitiveCompare:b[@"name"]];}];[self.tableView reloadData];
}
- (NSArray*)shown{if(_expanded.length){for(NSDictionary*f in _folders)if([f[@"id"]isEqual:_expanded])return f[@"items"];return @[];}return!_query.length?_all:[_all filteredArrayUsingPredicate:[NSPredicate predicateWithBlock:^BOOL(NSDictionary*x,NSDictionary*b){return[x[@"name"] localizedCaseInsensitiveContainsString:_query];}]];}
- (NSInteger)numberOfSectionsInTableView:(UITableView*)t{return 2;}
- (NSString*)tableView:(UITableView*)t titleForHeaderInSection:(NSInteger)s{return s==0?@"文件夹":(_expanded.length?@"文件夹内快捷指令":@"全部快捷指令");}
- (NSInteger)tableView:(UITableView*)t numberOfRowsInSection:(NSInteger)s{return s==0?_folders.count:self.shown.count?:1;}
- (UITableViewCell*)tableView:(UITableView*)t cellForRowAtIndexPath:(NSIndexPath*)p{UITableViewCell*c=[t dequeueReusableCellWithIdentifier:@"sc"]?:[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleDefault reuseIdentifier:@"sc"];if(p.section==0){NSDictionary*f=_folders[p.row];ABMCApplyLargeIcon(c,ABMCTintedIcon(@"folder.fill",nil));c.textLabel.text=f[@"name"];ABMCApplyActionTextStyle(c,UIColor.labelColor);c.accessoryType=[f[@"id"]isEqual:_expanded]?UITableViewCellAccessoryDetailButton:UITableViewCellAccessoryDisclosureIndicator;return c;}NSArray*v=self.shown;if(!v.count){c.textLabel.text=_expanded.length?@"该文件夹没有可读取的快捷指令":@"未读取到快捷指令";return c;}NSDictionary*x=v[p.row];NSString*k=[@"shortcut." stringByAppendingString:x[@"id"]],*token=ABMCDisplayIconToken(k,@"");ABMCApplyLargeIcon(c,ABMCTintedIcon(token,nil)?:ABMCWorkflowIconImage([x[@"glyph"]integerValue],[x[@"color"]longLongValue]));ABMCApplyActionTextStyle(c,UIColor.labelColor);c.textLabel.text=ABMCDisplayTitle(k,x[@"name"]);NSString*a=[NSString stringWithFormat:@"shortcutid:%@|%@|%@|%@",x[@"id"],x[@"name"],x[@"glyph"],x[@"color"]];c.accessoryType=[ABMCSelectedActions(_key)containsObject:a]?UITableViewCellAccessoryCheckmark:0;ABMCInstallPresentationLongPress(c,self,k,c.textLabel.text,token,^{[self.tableView reloadData];});return c;}
- (void)tableView:(UITableView*)t didSelectRowAtIndexPath:(NSIndexPath*)p{if(p.section==0){NSDictionary*f=_folders[p.row];_expanded=[f[@"id"] isEqual:_expanded]?nil:[f[@"id"] copy];[t reloadData];return;}NSArray*v=self.shown;if(!v.count)return;NSDictionary*x=v[p.row];NSString*a=[NSString stringWithFormat:@"shortcutid:%@|%@|%@|%@",x[@"id"],x[@"name"],x[@"glyph"],x[@"color"]];NSMutableArray*z=[ABMCSelectedActions(_key)mutableCopy];if([z containsObject:a])[z removeObject:a];else if(z.count<8)[z addObject:a];else return;ABMCStoreSelectedActions(_key,z);[self refreshHeader];[t reloadData];}
- (void)searchBar:(UISearchBar*)s textDidChange:(NSString*)text{_query=[text copy]?:@"";_expanded=nil;[self.tableView reloadData];}@end
